#!/usr/bin/env bash
# Interactive, one-off administrator setup using isolated peer-auth PostgreSQL role.
set -euo pipefail
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
umask 077
[[ "$EUID" -eq 0 && $# -eq 0 && -t 0 && -t 1 ]] || {
  echo "Run interactively with sudo"; exit 64;
}
envfile=/etc/careeragency/auth.env
[[ -f "$envfile" && ! -L "$envfile" ]] || exit 73
[[ "$(stat -c %a "$envfile")" == 600 ]] || exit 73
[[ "$(stat -c %U "$envfile")" == root ]] || exit 73
[[ -x /opt/careeragency/auth-current/.venv/bin/python ]] || exit 73
cd /opt/careeragency/auth-current
set -a
# File generated by protected configure-auth-secrets.py and owned by root.
# No shell output or GitHub Actions logging of secret values.
. "$envfile"
set +a
export CAREER_AUTH_ALLOW_ADMIN_BOOTSTRAP=YES_ONCE
runuser -u careeragency_auth -- .venv/bin/python -m authservice.bootstrap_admin
unset CAREER_AUTH_SMTP_PASS CAREER_AUTH_TOTP_KEY CAREER_AUTH_ALLOW_ADMIN_BOOTSTRAP
logger -p authpriv.notice -t careeragency-auth "ADMIN_BOOTSTRAP invoked=interactive"
echo "auth_admin=created"
echo "auth_admin_mfa=enrollment_required_on_first_login"
